Here is the commit message:
mptcp: fix scheduling with atomic in timestamp sockopt

Using lock_sock_fast() (atomic context) around sock_set_timestamp()
and sock_set_timestamping() is unsafe, as both helpers can sleep.

Replace lock_sock_fast() with sleepable lock_sock()/release_sock()
to avoid scheduling while atomic panic.

Fixes: 9061f24bf82e ("mptcp: sockopt: propagate timestamp request to subflows")
Cc: stable@vger.kernel.org
Reported-by: Sashiko <sashiko-bot@kernel.org>
Closes: https://sashiko.dev/#/patchset/20260420093343.16443-1-gang.yan@linux.dev
Signed-off-by: Gang Yan <yangang@kylinos.cn>
Reviewed-by: Matthieu Baerts (NGI0) <matttbe@kernel.org>
Signed-off-by: Matthieu Baerts (NGI0) <matttbe@kernel.org>
Link: https://patch.msgid.link/20260427-net-mptcp-misc-fixes-7-1-rc2-v1-2-7432b7f279fa@kernel.org
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug is caused by using `lock_sock_fast()` (which acquires a lock in atomic context) before calling `sock_set_timestamp()` and `sock_set_timestamping()`, both of which can sleep. This results in a "scheduling while atomic" panic because sleeping functions are invoked while holding an atomic lock.

Here is the patch:

 static int mptcp_setsockopt_sol_socket_tstamp(struct mptcp_sock *msk, int optname, int val)
 {
 	sockptr_t optval = KERNEL_SOCKPTR(&val);
 	struct mptcp_subflow_context *subflow;
 	struct sock *sk = (struct sock *)msk;
 	int ret;

 	ret = sock_setsockopt(sk->sk_socket, SOL_SOCKET, optname,
 			      optval, sizeof(val));
 	if (ret)
 		return ret;

 	lock_sock(sk);
 	mptcp_for_each_subflow(msk, subflow) {
 		struct sock *ssk = mptcp_subflow_tcp_sock(subflow);
-		bool slow = lock_sock_fast(ssk);

+		lock_sock(ssk);
 		sock_set_timestamp(ssk, optname, !!val);
-		unlock_sock_fast(ssk, slow);
+		release_sock(ssk);
 	}

 	release_sock(sk);
 	return 0;
 }


 static int mptcp_setsockopt_sol_socket_timestamping(struct mptcp_sock *msk,
 						    int optname,
 						    sockptr_t optval,
 						    unsigned int optlen)
 {
 	struct mptcp_subflow_context *subflow;
 	struct sock *sk = (struct sock *)msk;
 	struct so_timestamping timestamping;
 	int ret;

 	if (optlen == sizeof(timestamping)) {
 		if (copy_from_sockptr(&timestamping, optval,
 				      sizeof(timestamping)))
 			return -EFAULT;
 	} else if (optlen == sizeof(int)) {
 		memset(&timestamping, 0, sizeof(timestamping));

 		if (copy_from_sockptr(&timestamping.flags, optval, sizeof(int)))
 			return -EFAULT;
 	} else {
 		return -EINVAL;
 	}

 	ret = sock_setsockopt(sk->sk_socket, SOL_SOCKET, optname,
 			      KERNEL_SOCKPTR(&timestamping),
 			      sizeof(timestamping));
 	if (ret)
 		return ret;

 	lock_sock(sk);

 	mptcp_for_each_subflow(msk, subflow) {
 		struct sock *ssk = mptcp_subflow_tcp_sock(subflow);
-		bool slow = lock_sock_fast(ssk);

+		lock_sock(ssk);
 		sock_set_timestamping(ssk, optname, timestamping);
-		unlock_sock_fast(ssk, slow);
+		release_sock(ssk);
 	}

 	release_sock(sk);

 	return 0;
 }



